@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products..."
           @oninput="OnSearchInput"
           class="product-search-input" />

    @if (_isLoading)
    {
        <div class="product-search-status">Searching...</div>
    }
    else if (_errorMessage is not null)
    {
        <div class="product-search-error">@_errorMessage</div>
    }
    else if (_results is not null && _results.Count == 0)
    {
        <div class="product-search-status">No products found.</div>
    }

    @if (_results is { Count: > 0 })
    {
        <div class="product-search-results">
            @foreach (var product in _results)
            {
                <div class="product-card" @onclick="() => SelectProduct(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" class="product-card-image" />
                    <div class="product-card-name">@product.Name</div>
                    <div class="product-card-price">@product.Price.ToString("C")</div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<Product>? _results;
    private bool _isLoading;
    private string? _errorMessage;

    private Timer? _debounceTimer;
    private CancellationTokenSource? _searchCts;
    private string _lastQuery = string.Empty;

    private void OnSearchInput(ChangeEventArgs e)
    {
        var query = e.Value?.ToString() ?? string.Empty;
        _lastQuery = query;

        _debounceTimer?.Dispose();
        _debounceTimer = new Timer(DebounceElapsed, query, 300, Timeout.Infinite);
    }

    private async void DebounceElapsed(object? state)
    {
        var query = (string)state!;

        // Cancel any in-flight search
        _searchCts?.Cancel();
        _searchCts?.Dispose();
        _searchCts = new CancellationTokenSource();
        var ct = _searchCts.Token;

        if (string.IsNullOrWhiteSpace(query))
        {
            _results = null;
            _isLoading = false;
            _errorMessage = null;
            await InvokeAsync(StateHasChanged);
            return;
        }

        _isLoading = true;
        _errorMessage = null;
        await InvokeAsync(StateHasChanged);

        try
        {
            var results = await ProductService.SearchAsync(query, ct);

            if (ct.IsCancellationRequested)
                return;

            _results = results;
            _errorMessage = null;
        }
        catch (OperationCanceledException)
        {
            // Search was superseded; do nothing
            return;
        }
        catch (Exception)
        {
            if (ct.IsCancellationRequested)
                return;

            _results = null;
            _errorMessage = "Something went wrong. Please try again.";
        }
        finally
        {
            if (!ct.IsCancellationRequested)
            {
                _isLoading = false;
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    private async Task SelectProduct(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    public void Dispose()
    {
        _debounceTimer?.Dispose();
        _searchCts?.Cancel();
        _searchCts?.Dispose();
    }
}

